// Meta calls this once when you register the webhook. Change the token, then use the same token in Meta.
const VERIFY_TOKEN = 'CHANGE_ME_VERIFY_TOKEN';
const q = $input.first().json.query || {};
return [{ json: {
  ok: q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VERIFY_TOKEN,
  challenge: q['hub.challenge'] || ''
} }];

// Reads Meta's webhook payload and keeps only what the flow needs.
const body = $input.first().json.body || {};
const value = (((body.entry || [])[0] || {}).changes || [])[0]?.value || {};
const m = (value.messages || [])[0];
if (!m) return [{ json: { has_message: false } }];   // delivery receipts and other status updates
const contact = (value.contacts || [])[0];
let kind = 'other', text = '', reply_id = '', reply_title = '';
if (m.type === 'text') { kind = 'text'; text = (m.text && m.text.body) || ''; }
else if (m.type === 'interactive') {
  kind = 'button';
  const r = (m.interactive && (m.interactive.button_reply || m.interactive.list_reply)) || {};
  reply_id = r.id || ''; reply_title = r.title || '';
} else if (m.type === 'button') {
  kind = 'button'; reply_id = (m.button && m.button.payload) || ''; reply_title = (m.button && m.button.text) || '';
}
return [{ json: {
  has_message: true,
  phone_number_id: value.metadata && value.metadata.phone_number_id,
  wa_id: m.from, name: (contact && contact.profile && contact.profile.name) || '',
  msg_id: m.id, kind, text, reply_id, reply_title
} }];

